function formatar(valor: string | number | Date): string {
  if (typeof valor === 'string') return valor.trim();     // valor: string
  if (typeof valor === 'number') return valor.toFixed(2); // valor: number
  return valor.toISOString();                             // sobrou: Date
}

interface Gato { miar(): string }
interface Cachorro { latir(): string }

function falar(animal: Gato | Cachorro): string {
  if ('miar' in animal) return animal.miar(); // in: checa se a propriedade existe
  return animal.latir();                      // aqui só pode ser Cachorro
}

function mensagem(err: unknown): string {
  if (err instanceof Error) return err.message; // instanceof: checa a classe
  return String(err);
}

// Truthiness também estreita, mas cuidado: 0 e '' são falsy
function saudacao(nome?: string): string {
  return nome ? `Olá, ${nome}` : 'Olá, visitante';
}

console.log(formatar(3.14159));               // '3.14'
console.log(falar({ miar: () => 'miau' }));   // 'miau'
console.log(mensagem(new Error('falhou')));   // 'falhou'
console.log(saudacao(''));                    // 'Olá, visitante'

interface User { id: number; name: string }

// Type predicate: se retornar true, o TS passa a tratar x como User
function isUser(x: unknown): x is User {
  return (
    typeof x === 'object' && x !== null &&
    'id' in x && typeof x.id === 'number' &&
    'name' in x && typeof x.name === 'string'
  );
}

const dados: unknown = JSON.parse('{"id": 1, "name": "Ana"}');
if (isUser(dados)) {
  console.log(dados.name.toUpperCase()); // ✅ dados: User → 'ANA'
}

// Assertion function: lança se falhar; depois da chamada, o tipo fica estreito
function assertDefined<T>(valor: T, msg: string): asserts valor is NonNullable<T> {
  if (valor === undefined || valor === null) throw new Error(msg);
}

const porta = process.env.PORT;             // string | undefined
assertDefined(porta, 'PORT não definida');
console.log(Number(porta) + 1);             // ✅ porta: string

// Desde o TS 5.5, predicates simples são inferidos sozinhos
const ids: number[] = [1, undefined, 3].filter((n) => n !== undefined);
console.log(ids); // [ 1, 3 ]

type Pagamento =
  | { metodo: 'pix'; chave: string }
  | { metodo: 'cartao'; numero: string; parcelas: number }
  | { metodo: 'boleto'; vencimento: Date };

function descrever(p: Pagamento): string {
  switch (p.metodo) { // 'metodo' é o discriminante
    case 'pix':
      return `Pix para ${p.chave}`;      // p: { metodo: 'pix'; chave: string }
    case 'cartao':
      return `Cartão em ${p.parcelas}x`; // p.parcelas só existe aqui
    case 'boleto':
      return `Boleto até ${p.vencimento.toLocaleDateString('pt-BR')}`;
  }
}

console.log(descrever({ metodo: 'cartao', numero: '4111...', parcelas: 3 })); // 'Cartão em 3x'

// Modelando estados sem combinações impossíveis
type Estado<T> =
  | { status: 'carregando' }
  | { status: 'sucesso'; dados: T }
  | { status: 'erro'; erro: Error };

function render(e: Estado<string[]>): string {
  if (e.status === 'sucesso') return e.dados.join(', ');
  if (e.status === 'erro') return `Erro: ${e.erro.message}`;
  return 'Carregando...';
}
// Com { carregando: boolean; dados?: T; erro?: Error } daria para ter
// carregando: true E erro ao mesmo tempo. Aqui, o tipo não deixa.
console.log(render({ status: 'sucesso', dados: ['a', 'b'] })); // 'a, b'

function assertNever(x: never): never {
  throw new Error(`Caso não tratado: ${JSON.stringify(x)}`);
}

type Forma =
  | { tipo: 'circulo'; raio: number }
  | { tipo: 'quadrado'; lado: number };

function area(f: Forma): number {
  switch (f.tipo) {
    case 'circulo':
      return Math.PI * f.raio ** 2;
    case 'quadrado':
      return f.lado ** 2;
    default:
      return assertNever(f); // f: never, porque todos os casos foram tratados
  }
}

// Alguém adicionou um caso novo e esqueceu de tratar:
type Forma2 = Forma | { tipo: 'triangulo'; base: number; altura: number };

function area2(f: Forma2): number {
  switch (f.tipo) {
    case 'circulo':
      return Math.PI * f.raio ** 2;
    case 'quadrado':
      return f.lado ** 2;
    default:
      // @ts-expect-error: 'triangulo' não foi tratado, então f não é never
      return assertNever(f);
  }
}
// O compilador aponta o esquecimento ANTES de rodar. Sem o assertNever,
// area2 devolveria undefined em silêncio para triângulos.
console.log(area({ tipo: 'quadrado', lado: 3 })); // 9

type Rota = { metodo: 'GET' | 'POST'; caminho: `/${string}` };

// Anotação: o tipo vira Record<string, Rota> e as chaves reais se perdem
const rotas1: Record<string, Rota> = {
  listar: { metodo: 'GET', caminho: '/users' },
};
console.log(rotas1.qualquerCoisa); // compila, e em runtime é undefined

// satisfies: valida contra o tipo, mas mantém o tipo inferido
const rotas = {
  listar: { metodo: 'GET', caminho: '/users' },
  criar: { metodo: 'POST', caminho: '/users' },
} satisfies Record<string, Rota>;

const metodo: 'GET' = rotas.listar.metodo; // literal preservado, não string
// @ts-expect-error: com satisfies, chave inexistente é erro
console.log(rotas.qualquerCoisa);

const invalidas = {
  // @ts-expect-error: 'PATCH' não é um método permitido em Rota
  editar: { metodo: 'PATCH', caminho: '/users' },
} satisfies Record<string, Rota>;
